import {deliveryDate,total,preparation} from './domain.js';
const photo=(id)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=550&q=80`;
const products=[
{id:'bayam',name:'Bayam Hijau',unit:'1 ikat · ±200 g',price:5000,category:'Sayuran',image:photo('photo-1576045057995-568f588f82fb'),tag:'Favorit tetangga'},
{id:'wortel',name:'Wortel Segar',unit:'1 bungkus · 500 g',price:8000,category:'Sayuran',image:photo('photo-1445282768818-728615cc910a'),tag:'Pilihan hari ini'},
{id:'tomat',name:'Tomat Merah',unit:'1 bungkus · 500 g',price:9000,category:'Sayuran',image:photo('photo-1546094096-0df4bcaaa337'),tag:''},
{id:'brokoli',name:'Brokoli Hijau',unit:'1 bonggol · ±300 g',price:12000,category:'Sayuran',image:photo('photo-1459411621453-7b03977f4bfc'),tag:'Segar dari pasar'},
{id:'pisang',name:'Pisang Cavendish',unit:'1 sisir kecil · ±700 g',price:18000,category:'Buah',image:photo('photo-1571771894821-ce9b6c11b08e'),tag:'Manis alami'},
{id:'jeruk',name:'Jeruk Manis',unit:'1 bungkus · 500 g',price:15000,category:'Buah',image:photo('photo-1547514701-42782101795e'),tag:''},
{id:'ayam',name:'Ayam Potong',unit:'1 porsi · ±500 g',price:22000,category:'Lauk',image:photo('photo-1604503468506-a8da13d82791'),tag:'Bisa minta dipotong'},
{id:'telur',name:'Telur Ayam',unit:'1 paket · 6 butir',price:14000,category:'Dapur',image:photo('photo-1506976785307-8732e854ad03'),tag:'Stok dapur'},
{id:'ikan',name:'Ikan Segar',unit:'1 porsi · ±500 g',price:25000,category:'Lauk',image:photo('photo-1510130387422-82bed34b37e9'),tag:'Jenis dikonfirmasi'},
{id:'kentang',name:'Kentang',unit:'1 bungkus · 500 g',price:10000,category:'Sayuran',image:photo('photo-1518977676601-b53f82aba655'),tag:''},
{id:'alpukat',name:'Alpukat',unit:'1 porsi · ±500 g',price:18000,category:'Buah',image:photo('photo-1523049673857-eb18f1d7b578'),tag:''},
{id:'cabai',name:'Cabai Merah',unit:'1 bungkus · 100 g',price:7000,category:'Dapur',image:photo('photo-1588252303782-cb80119abd6d'),tag:''}
];
const $=s=>document.querySelector(s);
const money=v=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v);
const dateLabel=date=>new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',weekday:'long',day:'numeric',month:'long'}).format(date);
const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let cart=read('hemart-cart',{});if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};
cart=Object.fromEntries(Object.entries(cart).filter(([id,qty])=>products.some(p=>p.id===id)&&Number.isInteger(qty)&&qty>0&&qty<=20));
let orders=read('hemart-orders',[]);if(!Array.isArray(orders))orders=[];
let category='Semua',query='',sellerMode='orders';
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{toast('Penyimpanan perangkat tidak tersedia.');return false;}}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function qtyControl(id){return `<div class="quantity"><button data-change="${id}" data-delta="-1" aria-label="Kurangi ${esc(products.find(p=>p.id===id).name)}">−</button><span>${cart[id]}</span><button data-change="${id}" data-delta="1" ${cart[id]>=20?'disabled':''} aria-label="Tambah ${esc(products.find(p=>p.id===id).name)}">+</button></div>`;}
function renderProducts(){const shown=products.filter(p=>(category==='Semua'||p.category===category)&&p.name.toLowerCase().includes(query));$('#products').innerHTML=shown.map(p=>`<article class="product-card"><div class="product-image"><img src="${p.image}" alt="${p.name}" loading="lazy">${p.tag?`<span class="product-tag">${p.tag}</span>`:''}</div><div class="product-body"><h3>${p.name}</h3><span class="unit">${p.unit}</span><div class="price-row"><strong>${money(p.price)} <small>/ porsi</small></strong>${cart[p.id]?qtyControl(p.id):`<button class="add" data-change="${p.id}" data-delta="1" aria-label="Tambah ${p.name} ke keranjang">+</button>`}</div></div></article>`).join('');$('#empty').hidden=shown.length>0;$('#result-count').textContent=`${shown.length} produk pilihan`;$('#cart-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);}
function renderCategories(){const icons=['✦','♧','◉','♨','▦'];$('#categories').innerHTML=['Semua','Sayuran','Buah','Lauk','Dapur'].map((name,i)=>`<button class="category ${category===name?'active':''}" data-category="${name}" aria-pressed="${category===name}"><span>${icons[i]}</span>${name==='Semua'?'Semua produk':name}</button>`).join('');}
function renderCart(){const entries=Object.entries(cart);$('#cart-items').innerHTML=entries.length?entries.map(([id,qty])=>{const p=products.find(p=>p.id===id);return `<div class="cart-item"><img src="${p.image}" alt=""><div class="cart-item-info"><h3>${p.name}</h3><small>${money(p.price*qty)} · ${p.unit}</small></div>${qtyControl(id)}</div>`;}).join(''):'<div class="empty">Keranjang masih kosong.<br>Yuk, pilih bahan untuk besok pagi.</div>';$('#cart-summary').innerHTML=entries.length?`<div class="summary-row"><span>Perkiraan belanja</span><b>${money(total(cart,products))}</b></div><p class="muted">Harga contoh. Berat aktual dan ketersediaan dikonfirmasi setelah belanja pasar. Ongkir belum ditentukan.</p><button class="primary full" id="checkout-start">Lanjut pengantaran →</button>`:'';}
function showPage(page){for(const name of ['shop','orders','about','seller'])$(`#${name}-page`).hidden=name!==page;document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='orders')renderOrders();if(page==='seller')renderSeller();window.scrollTo({top:0,behavior:'instant'});}
function orderCard(order,seller=false){return `<article class="order-card"><div class="order-top"><div><h3>${esc(order.id)}</h3><span class="muted">${esc(order.delivery)} · Mulai 06.00 WIB</span></div><span class="status">${esc(order.status)}</span></div>${seller?`<p><b>${esc(order.name)}</b> · ${esc(order.phone)}<br>${esc(order.address)}<br>Barang kosong: ${esc(order.substitution)}${order.notes?`<br>Catatan: ${esc(order.notes)}`:''}</p>`:''}<ul>${order.items.map(p=>`<li>${p.qty} × ${esc(p.name)} <span class="muted">(${esc(p.unit)})</span></li>`).join('')}</ul><p><b>Perkiraan ${money(order.total)}</b> <span class="muted">· Tunai saat diterima · Ongkir belum ditentukan</span></p>${seller?`<label>Status demo <select data-order-status="${esc(order.id)}">${['Diterima','Dikonfirmasi','Dikemas','Dalam perjalanan','Selesai'].map(s=>`<option ${order.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`:`<button class="secondary" data-reorder="${esc(order.id)}">Belanja lagi ↗</button>`}</article>`;}
function renderOrders(){$('#orders-list').innerHTML=orders.length?orders.map(o=>orderCard(o)).join(''):'<div class="empty">Belum ada pesanan.<br>Pesanan demo Anda akan muncul di sini.</div>';}
function renderSeller(){if(sellerMode==='prep'){const grouped=Object.groupBy(orders.filter(o=>o.status!=='Selesai'),o=>o.delivery);$('#seller-content').innerHTML=Object.entries(grouped).map(([day,dayOrders])=>`<article class="order-card"><h2>${esc(day)}</h2><p class="muted">Gabungan ${dayOrders.length} pesanan aktif. Jumlah dihitung per porsi kemasan.</p><table><thead><tr><th>Bahan</th><th>Porsi</th></tr></thead><tbody>${preparation(dayOrders).map(p=>`<tr><td>${esc(p.name)}<br><small class="muted">${esc(p.unit)}</small></td><td>${p.qty}</td></tr>`).join('')}</tbody></table></article>`).join('')||'<div class="empty">Belum ada bahan yang perlu dibeli.</div>';}else $('#seller-content').innerHTML=orders.length?orders.map(o=>orderCard(o,true)).join(''):'<div class="empty">Belum ada pesanan demo. Coba checkout dari halaman Belanja.</div>';}
function refreshDelivery(){const delivery=deliveryDate();$('#delivery-label').textContent=`Pengantaran ${dateLabel(delivery)}`;return delivery;}
document.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.change){const id=target.dataset.change;if(!products.some(p=>p.id===id))return;const next=Math.max(0,Math.min(20,(cart[id]||0)+Number(target.dataset.delta)));if(next)cart[id]=next;else delete cart[id];save('hemart-cart',cart);renderProducts();renderCart();}if(target.dataset.category){category=target.dataset.category;renderCategories();renderProducts();}if(target.dataset.page)showPage(target.dataset.page);if(target.dataset.close)$(`#${target.dataset.close}`).close();if(target.id==='cart-open'){renderCart();$('#cart-dialog').showModal();}if(target.id==='checkout-start'){$('#cart-dialog').close();const delivery=refreshDelivery();$('.checkout-delivery').textContent=`Pengantaran ${dateLabel(delivery)}, mulai 06.00 WIB sesuai rute. Estimasi belanja ${money(total(cart,products))}.`;$('#checkout-dialog').dataset.delivery=delivery.toISOString();$('#checkout-dialog').showModal();}if(target.dataset.reorder){const order=orders.find(o=>o.id===target.dataset.reorder);for(const item of order.items)if(products.some(p=>p.id===item.id))cart[item.id]=Math.min(20,(cart[item.id]||0)+item.qty);save('hemart-cart',cart);renderProducts();renderCart();$('#cart-dialog').showModal();}if(target.id==='show-prep'||target.id==='show-orders'){sellerMode=target.id==='show-prep'?'prep':'orders';renderSeller();}});
$('#search').addEventListener('input',event=>{query=event.target.value.trim().toLowerCase();renderProducts();});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){event.preventDefault();showPage('shop');$('#search').focus();}});
document.addEventListener('change',event=>{if(event.target.dataset.orderStatus){const order=orders.find(o=>o.id===event.target.dataset.orderStatus);order.status=event.target.value;save('hemart-orders',orders);renderSeller();}});
$('#checkout-form').addEventListener('submit',event=>{event.preventDefault();if(!Object.keys(cart).length)return;const delivery=deliveryDate();if(delivery.toISOString()!==$('#checkout-dialog').dataset.delivery){$('#checkout-dialog').dataset.delivery=delivery.toISOString();$('.checkout-delivery').textContent=`Batas waktu sudah lewat. Jadwal baru: ${dateLabel(delivery)}, mulai 06.00 WIB. Silakan simpan kembali untuk menyetujui.`;return;}const data=Object.fromEntries(new FormData(event.target));if(!data.name.trim()||!data.address.trim()){toast('Nama dan alamat tidak boleh kosong.');return;}const order={...data,id:'HM-'+crypto.randomUUID().slice(0,8).toUpperCase(),createdAt:new Date().toISOString(),delivery:dateLabel(delivery),status:'Diterima',items:Object.entries(cart).map(([id,qty])=>({...products.find(p=>p.id===id),qty})),total:total(cart,products)};const next=[order,...orders];if(!save('hemart-orders',next))return;orders=next;cart={};save('hemart-cart',cart);event.target.reset();$('#checkout-dialog').close();renderProducts();showPage('orders');toast('Pesanan demo tersimpan di perangkat ini.');});
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('#install').hidden=false;});$('#install').addEventListener('click',async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#install').hidden=true;});window.addEventListener('appinstalled',()=>{$('#install').hidden=true;});window.addEventListener('offline',()=>toast('Anda offline. Keranjang tetap tersimpan di perangkat.'));
renderCategories();renderProducts();refreshDelivery();setInterval(refreshDelivery,60000);
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>console.warn('Offline mode unavailable'));
